<?php
declare(strict_types=1);
require dirname(__DIR__) . '/src/bootstrap.php';
use App\Core\Security;
use App\Core\LocalState;
Security::requireAuth();
Security::startSession();
$stateStore = new LocalState();
$state = $stateStore->all();
$views = [
 'campaigns'=>['Campaigns','Compare delivery, spend and outcomes across connected ad platforms.'],
 'creatives'=>['Creatives','Review creative performance and fatigue signals before testing new variants.'],
 'insights'=>['Insights','Read normalized performance metrics from Meta and Google Ads.'],
 'approvals'=>['Approvals','Review proposed changes before anything can be executed.'],
 'automations'=>['Automations','Control safe automation policies, schedules and the global kill switch.'],
 'activity'=>['Activity log','Review sync jobs, recommendations and administrative events.'],
 'settings'=>['Workspace settings','Configure workspace preferences and safe-mode controls.'],
];
$view=(string)($_GET['view']??'campaigns'); if(!isset($views[$view]))$view='campaigns'; [$title,$description]=$views[$view];
$panelSettings = $state['settings'];
$panelSettings['notifications'] = !empty($panelSettings['notifications']) ? 'on' : 'off';
$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Security::verifyCsrf($_POST['_csrf']??null))$message=['error','Security token expired.'];
 elseif($view==='settings'){
  $state = $stateStore->update(function(array $current): array {
   $current['settings']['currency']=in_array($_POST['currency']??'', ['USD','BDT','EUR','GBP'],true)?$_POST['currency']:'USD';
   $current['settings']['timezone']=in_array($_POST['timezone']??'', ['UTC','Asia/Dhaka','Asia/Kolkata','America/New_York'],true)?$_POST['timezone']:'UTC';
   $current['settings']['date_range']=in_array($_POST['date_range']??'', ['7','30','90'],true)?$_POST['date_range']:'7';
   $current['settings']['notifications']=isset($_POST['notifications']);
   $current['updated_at']=date(DATE_ATOM); return $current;
  });
  $panelSettings=$state['settings']; $panelSettings['notifications']=!empty($panelSettings['notifications'])?'on':'off';
  $message=['success','Workspace preferences saved.'];
 }
}
$s=$panelSettings;
$nav=['campaigns'=>'◉ Campaigns','creatives'=>'◌ Creatives','insights'=>'⌁ Insights','approvals'=>'✓ Approvals','automations'=>'↗ Automations','activity'=>'≡ Activity log','settings'=>'⚙ Workspace settings'];
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function content(string $view,array $s):string{
 $safe='<div class="notice"><b>Safe mode is active.</b> This local build never changes ads or budgets. Connect providers before live actions.</div>';
 if($view==='settings')return '<div class="settings-grid"><div class="card"><div class="section-head"><div><h2>Workspace preferences</h2><p>These controls are active immediately in this browser session.</p></div><span class="pill green">Saved locally</span></div><form method="post"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><div class="form-grid"><label>Reporting currency<select name="currency"><option '.($s['currency']==='USD'?'selected':'').'>USD</option><option '.($s['currency']==='BDT'?'selected':'').'>BDT</option><option '.($s['currency']==='EUR'?'selected':'').'>EUR</option><option '.($s['currency']==='GBP'?'selected':'').'>GBP</option></select></label><label>Timezone<select name="timezone"><option>UTC</option><option '.($s['timezone']==='Asia/Dhaka'?'selected':'').'>Asia/Dhaka</option><option '.($s['timezone']==='Asia/Kolkata'?'selected':'').'>Asia/Kolkata</option><option '.($s['timezone']==='America/New_York'?'selected':'').'>America/New_York</option></select></label><label>Default date range<select name="date_range"><option value="7" '.($s['date_range']==='7'?'selected':'').'>Last 7 days</option><option value="30" '.($s['date_range']==='30'?'selected':'').'>Last 30 days</option><option value="90" '.($s['date_range']==='90'?'selected':'').'>Last 90 days</option></select></label><label class="check"><input type="checkbox" name="notifications" '.($s['notifications']==='on'?'checked':'').'> Daily report notifications</label></div><button class="button" type="submit">Save preferences</button></form></div><div class="card"><h2>Safety controls</h2><p>These are intentionally locked until production credentials and approval policy are verified.</p><div class="safety-row"><span>Global kill switch</span><b class="pill green">ON</b></div><div class="safety-row"><span>Live writes</span><b class="pill amber">DISABLED</b></div><div class="safety-row"><span>Approval required</span><b class="pill blue">YES</b></div></div></div>';
 $data=['campaigns'=>['Connected accounts','0','Connect Meta or Google to load campaigns.'], 'creatives'=>['Creative library','0','Creative-level metrics will appear after the first sync.'], 'insights'=>['Reporting data','0 rows','Run a read-only sync to populate normalized insights.'], 'approvals'=>['Pending approvals','0','No actions are pending. New proposals will appear here for review.'], 'automations'=>['Automation rules','Read-only','Rules can be configured after provider setup; live execution remains blocked.'], 'activity'=>['Recorded events','0','Sync and audit events will appear here.']]; [$label,$metric,$hint]=$data[$view];
 return $safe.'<div class="grid"><div class="card"><h2>'.$label.'</h2><div class="metric">'.$metric.'</div><p>'.$hint.'</p></div><div class="card"><h2>Next step</h2><p>Open Workspace settings, choose your reporting preferences, then connect a provider account.</p><a class="button secondary" href="/settings.php">Open settings</a></div><div class="card"><h2>Protection</h2><div class="metric green-text">ON</div><p>Global kill switch and read-only mode are enabled.</p></div></div><div class="card table-card"><h2>Workflow status</h2><table><tr><th>Stage</th><th>Status</th><th>Action</th></tr><tr><td>Configuration</td><td><span class="pill amber">Pending</span></td><td><a href="?view=settings">Configure</a></td></tr><tr><td>Provider sync</td><td><span class="pill blue">Not started</span></td><td>Requires credentials</td></tr><tr><td>Execution</td><td><span class="pill green">Blocked safely</span></td><td>Approval required</td></tr></table></div>';
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · Stratmark Adpilot</title><style>:root{--navy:#12243a;--ink:#172231;--muted:#718096;--line:#e7edf3;--canvas:#f6f8fb;--white:#fff;--blue:#2864e8;--green:#15966b;--amber:#b87312}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.5 system-ui,-apple-system,sans-serif}.shell{display:flex;min-height:100vh}.sidebar{width:238px;flex:none;background:var(--navy);color:#d8e1ec;padding:25px 15px;display:flex;flex-direction:column}.brand{display:flex;gap:11px;align-items:center;padding:0 12px 28px;color:#fff}.mark{width:34px;height:34px;border-radius:10px;background:#4f8aff;display:grid;place-items:center;font-weight:800}.brand small{display:block;color:#94aac4;font-size:10px}.nav-label{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#7188a3;padding:12px 13px 8px}.nav a{display:block;padding:11px 13px;border-radius:8px;margin:2px 0;color:#b8c7d9;text-decoration:none}.nav a:hover,.nav a.active{background:#1e3856;color:#fff}.sidebar-bottom{margin-top:auto;border-top:1px solid #29415d;padding:16px 12px;color:#91a6bd;font-size:11px}.main{min-width:0;flex:1}.topbar{height:76px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 34px}.topbar a,.card a{color:var(--blue);text-decoration:none}.content{max-width:1200px;margin:auto;padding:32px 34px}.eyebrow{color:var(--blue);font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:1px}.title{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.title h1{font-size:27px;margin:5px 0}.title p,.card p{color:var(--muted);margin:0}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:21px;box-shadow:0 8px 24px #162b460a}.card h2{font-size:15px;margin:0 0 7px}.grid,.settings-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.settings-grid{grid-template-columns:1.5fr 1fr}.notice{background:#edf3ff;color:#315caa;padding:14px;border-radius:9px;margin-bottom:18px;font-size:12px}.metric{font-size:27px;font-weight:750;margin:15px 0 3px}.green-text{color:var(--green)}.button{display:inline-block;background:var(--blue);color:#fff!important;border:0;border-radius:7px;padding:10px 15px;font-weight:700;cursor:pointer;margin-top:18px}.button.secondary{background:#edf3ff;color:var(--blue)!important;margin-top:12px}.section-head{display:flex;justify-content:space-between;gap:15px;margin-bottom:20px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}label{font-size:12px;font-weight:700}select{display:block;width:100%;margin-top:7px;padding:11px;border:1px solid #dbe3ec;border-radius:7px;background:white;font:inherit}.check{display:flex;align-items:center;gap:8px;padding-top:28px}.check input{accent-color:var(--blue)}.pill{display:inline-block;border-radius:20px;padding:4px 9px;font-size:10px;font-weight:750}.green{background:#e8f8f1;color:var(--green)}.amber{background:#fff5e5;color:var(--amber)}.blue{background:#edf3ff;color:var(--blue)}.safety-row{display:flex;justify-content:space-between;border-top:1px solid #eef2f5;padding:14px 0}.table-card{margin-top:16px}.table-card table{width:100%;border-collapse:collapse;margin-top:12px}.table-card th,.table-card td{text-align:left;padding:12px 8px;border-top:1px solid #eef2f5;font-size:12px}.table-card th{color:#8997a8;text-transform:uppercase;font-size:10px}.flash{padding:12px;border-radius:8px;margin-bottom:16px;font-size:12px}.flash.success{background:#e8f8f1;color:#137754}.flash.error{background:#fff0f0;color:#b23c48}.mobile-menu,.sidebar-close,.menu-backdrop{display:none}@media(max-width:640px){.sidebar{position:fixed;z-index:20;inset:0 auto 0 0;width:270px;transform:translateX(-105%);transition:transform .2s ease;box-shadow:12px 0 28px #0a1e3733}.sidebar-close{display:block;position:absolute;right:13px;top:18px;background:transparent;color:#b8c7d9;border:0;font-size:22px}.mobile-menu{display:inline-block;background:transparent;border:0;font-size:20px;margin-right:8px}.menu-backdrop{display:none}body.menu-open .sidebar{transform:translateX(0)}body.menu-open .menu-backdrop{display:block;position:fixed;z-index:10;inset:0;background:#0a192d6b}.shell{display:block}.topbar{height:62px;padding:0 16px}.topbar strong{display:flex;align-items:center}.content{padding:24px 15px}.title{display:block}.grid,.settings-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.check{padding-top:0}}
</style></head><body><div class="shell"><div class="menu-backdrop"></div><aside class="sidebar"><button class="sidebar-close" type="button">×</button><div class="brand"><div class="mark">SA</div><div><strong>Stratmark</strong><small>ADPILOT</small></div></div><nav class="nav"><div class="nav-label">Workspace</div><a href="/">▦ Overview</a><?php foreach($nav as $k=>$label):?><a class="<?= $k===$view?'active':''?>" href="<?= $k === 'settings' ? '/settings.php' : '?view='.e($k) ?>"><?=e($label)?></a><?php endforeach;?></nav><div class="sidebar-bottom">● <?=e($state['demo_mode'] ? 'Demo mode' : 'Connected workspace')?><br><?=e($state['settings']['notifications'] ? 'Notifications enabled' : 'Notifications disabled')?></div></aside><main class="main"><header class="topbar"><strong><button class="mobile-menu" type="button" aria-label="Open menu">☰</button><?=e($title)?></strong><a href="/logout.php">Sign out</a></header><section class="content"><div class="title"><div><div class="eyebrow">Stratmark Adpilot</div><h1><?=e($title)?></h1><p><?=e($description)?></p></div></div><?php if($message):?><div class="flash <?=e($message[0])?>"><?=e($message[1])?></div><?php endif;?><?=content($view,$s)?></section></main></div><script>(()=>{const b=document.body,o=document.querySelector('.mobile-menu'),c=document.querySelector('.sidebar-close'),x=document.querySelector('.menu-backdrop'),links=document.querySelectorAll('.sidebar a');const set=v=>b.classList.toggle('menu-open',v);o?.addEventListener('click',()=>set(true));c?.addEventListener('click',()=>set(false));x?.addEventListener('click',()=>set(false));links.forEach(a=>a.addEventListener('click',()=>set(false)));document.addEventListener('keydown',e=>e.key==='Escape'&&set(false));})();</script></body></html>
